# security_models.py - Local request/response & normalization helpers for Key Management & Encryption\n\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nimport base64\nfrom typing import Any, Dict\n\n# ---------------------------------------------------------------------------\n# Basic payload models\n# ---------------------------------------------------------------------------\n\n@dataclass\nclass PlaintextPayload:\n    data: str  # original plaintext string\n\n@dataclass\nclass EncryptedResult:\n    encrypted_data_key: bytes  # ciphertext of the data key (as returned by KMS)\n    ciphertext: bytes  # payload encrypted with the plaintext data key\n\n@dataclass\nclass EncryptedEnvelope:\n    encrypted_data_key: bytes  # base64‑encoded for easy transport\n    ciphertext: bytes  # base64‑encoded for easy transport\n\n    @classmethod\n    def from_response(cls, resp: Dict[str, Any]) -> EncryptedEnvelope:\n        \"\"\"Create EncryptedEnvelope from raw KMS response dict.\"\"\"\n        return cls(\n            encrypted_data_key=base64.b64encode(resp['CiphertextBlob']),\n            ciphertext=base64.b64encode(resp['Plaintext'])\n        )\n\n# ---------------------------------------------------------------------------\n# Result models for verification / signing\n# ---------------------------------------------------------------------------\n\n@dataclass\nclass SignatureResult:\n    signature: bytes  # raw signature bytes (or base64 if preferred)\n\n    @classmethod\n    def from_response(cls, resp: Dict[str, Any]) -> SignatureResult:\n        return cls(signature=resp['Signature'])\n\n# ---------------------------------------------------------------------------\n# Normalization helpers\n# ---------------------------------------------------------------------------\n\ndef normalize_response(resp: Dict[str, Any]) -> Dict[str, Any]:\n    \"\"\"Convert common KMS response values to consistent types.\n    \"\"\"\n    normalized = {}\n    for k, v in resp.items():\n        if isinstance(v, (bytes, bytearray)):\n            normalized[k] = v  # keep binary\n        else:\n            normalized[k] = str(v)\n    return normalized\n\n# End of helper file\n